import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import {
  mix,
  smoothstep,
  uv,
  vec3,
} from 'three/tsl';
import { gsap } from 'gsap';

function createCapsuleShape(THREE, width, height, radius) {
  const shape = new THREE.Shape();
  const x = width * 0.5;
  const y = height * 0.5;
  const r = Math.min(radius, x, y);

  shape.moveTo(-x + r, -y);
  shape.lineTo(x - r, -y);
  shape.absarc(x - r, -y + r, r, -Math.PI * 0.5, 0);
  shape.lineTo(x, y - r);
  shape.absarc(x - r, y - r, r, 0, Math.PI * 0.5);
  shape.lineTo(-x + r, y);
  shape.absarc(-x + r, y - r, r, Math.PI * 0.5, Math.PI);
  shape.lineTo(-x, -y + r);
  shape.absarc(-x + r, -y + r, r, Math.PI, Math.PI * 1.5);
  shape.closePath();

  return shape;
}

function disposeObject(root) {
  root.traverse((object) => {
    if (object.geometry) object.geometry.dispose();

    if (!object.material) return;

    const materials = Array.isArray(object.material)
      ? object.material
      : [object.material];

    for (const material of materials) {
      if (material && material.dispose) material.dispose();
    }
  });
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CircleGeometry,
    ExtrudeGeometry,
    Color,
    PointLight,
  } = THREE;

  const root = new Group();
  root.name = 'journal-badge';

  const timelines = [];
  const primitiveCleanups = [];
  let disposed = false;

  const stage = new Group();
  stage.name = 'badge-stage';
  root.add(stage);

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    depthWrite: false,
  });

  const backdropGradient = smoothstep(0.0, 1.0, uv().y);
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.055, 0.055, 0.075),
      backdropGradient
    ),
    smoothstep(0.0, 1.0, uv().y)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  stage.add(backdrop);

  const shadowGeometry = new CircleGeometry(0.72, 48);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
  });
  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.name = 'badge-contact-shadow';
  contactShadow.scale.set(1.5, 0.42, 1);
  contactShadow.position.set(0, -0.42, -0.28);
  stage.add(contactShadow);

  const badgeGroup = new Group();
  badgeGroup.name = 'machined-journal-capsule';
  badgeGroup.position.z = 0.05;
  stage.add(badgeGroup);

  const outerShape = createCapsuleShape(THREE, 1.72, 0.62, 0.31);
  const outerGeometry = new ExtrudeGeometry(outerShape, {
    depth: 0.11,
    bevelEnabled: true,
    bevelSegments: 3,
    bevelSize: 0.035,
    bevelThickness: 0.025,
    curveSegments: 12,
  });
  outerGeometry.center();

  const outerMaterial = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    roughness: 0.52,
    metalness: 0.42,
  });
  const outerBadge = new Mesh(outerGeometry, outerMaterial);
  outerBadge.name = 'signal-red-edge-light';
  badgeGroup.add(outerBadge);

  const innerShape = createCapsuleShape(THREE, 1.54, 0.44, 0.22);
  const innerGeometry = new ExtrudeGeometry(innerShape, {
    depth: 0.075,
    bevelEnabled: true,
    bevelSegments: 3,
    bevelSize: 0.025,
    bevelThickness: 0.018,
    curveSegments: 12,
  });
  innerGeometry.center();

  const innerMaterial = new MeshStandardNodeMaterial({
    color: new Color('#16161d'),
    roughness: 0.68,
    metalness: 0.48,
  });
  const innerBadge = new Mesh(innerGeometry, innerMaterial);
  innerBadge.name = 'ink-capsule-face';
  innerBadge.position.z = 0.075;
  badgeGroup.add(innerBadge);

  const gearGroup = new Group();
  gearGroup.name = 'journal-gear-subject';
  gearGroup.scale.setScalar(0.36);
  gearGroup.position.set(0.69, 0, 0.2);
  badgeGroup.add(gearGroup);

  const rimLight = new PointLight(new Color('#ff2a38'), 0.82, 3.2, 2);
  rimLight.name = 'accent-rim-light';
  rimLight.position.set(0.8, 0.3, 1.1);
  badgeGroup.add(rimLight);

  const fillLight = new PointLight(new Color('#e8ecf2'), 0.38, 3.5, 2);
  fillLight.name = 'paper-fill-light';
  fillLight.position.set(-0.9, 0.55, 1.2);
  badgeGroup.add(fillLight);

  const entrance = gsap.timeline();
  timelines.push(entrance);
  entrance.fromTo(
    badgeGroup.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.42,
      ease: 'power3.out',
    }
  ).to(badgeGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, '<');

  const loadPromise = config.meshUrl
    ? ctx.glbLoader.loadGLB(config.meshUrl)
    : Promise.resolve(null);

  loadPromise
    .then((gltf) => {
      if (disposed || !gltf || !gltf.scene) return;

      const loadedScene = gltf.scene;
      loadedScene.name = 'gear-a-machined-metal';
      gearGroup.add(loadedScene);

      const box = new THREE.Box3().setFromObject(loadedScene);
      const center = box.getCenter(new THREE.Vector3());
      loadedScene.position.sub(center);
    })
    .catch(() => {});

  for (const primitive of config.cinematicPrimitives ?? []) {
    const applyPrimitive = ctx.primitives?.[primitive.name];
    if (typeof applyPrimitive !== 'function') continue;

    const result = applyPrimitive(root, primitive.params);
    if (result?.timeline) timelines.push(result.timeline);
    if (typeof result?.cleanup === 'function') {
      primitiveCleanups.push(result.cleanup);
    }
  }

  root.userData.handlers = {
    hover(active) {
      if (disposed) return;

      gsap.killTweensOf(badgeGroup.position);
      gsap.killTweensOf(badgeGroup.rotation);

      if (active) {
        gsap.to(badgeGroup.position, {
          y: 0.15,
          duration: 0.3,
          ease: 'power2.out',
        });
        gsap.to(badgeGroup.rotation, {
          z: -0.035,
          duration: 0.3,
          ease: 'power2.out',
        });
      } else {
        gsap.to(badgeGroup.position, {
          y: 0,
          duration: 0.42,
          ease: 'power3.out',
        });
        gsap.to(badgeGroup.rotation, {
          z: 0,
          duration: 0.42,
          ease: 'power3.out',
        });
      }
    },

    click() {
      if (disposed) return;

      const press = gsap.timeline();
      timelines.push(press);
      press.to(badgeGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
      }).to(badgeGroup.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.34,
        ease: 'back.out(2)',
      });

      ctx.emit('hub-journal.select', {
        node: root.name,
        source: 'journal-badge',
      });
    },
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const cleanup of primitiveCleanups) cleanup();
    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    gsap.killTweensOf(badgeGroup.position);
    gsap.killTweensOf(badgeGroup.rotation);
    gsap.killTweensOf(badgeGroup.scale);

    disposeObject(root);
  };

  return root;
}
